async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  if (!validation.valid) {
    reportValidationError(ws, validation.error);
    return;
  }
  if (validation.data.type === 'user_message') {
    return handleUserMessage(ws, session, orchestrator, validation.data.content, signal);
  }
}

async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    reportValidationError(ws, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') {
    handlePing(ws, message.timestamp);
    return;
  }
  if (message.type === 'list_sessions') {
    await handleListSessions(ws, session, sessionStore, message);
  }
}

function reportValidationError(ws: WebSocket, error: string): void {
  log.warn('message', 'validation failed', {error});
  sendError(ws, ErrorCodes.INVALID_MESSAGE, error);
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (sessionStore?.listFor === undefined) {
    sendSessionList(ws, []);
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, listOptionsOf(message));
    sendSessionList(ws, summaries.map(toSessionSummaryFrame));
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

function listOptionsOf(message: ListSessionsMessage): SessionListOptions {
  return {
    ...(message.limit !== undefined ? {limit: message.limit} : {}),
    ...(message.before !== undefined ? {before: message.before} : {}),
  };
}

function toSessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

